draw:
var k = 8.99e9;
var R = p.R, Q = p.Q * 1e-9, z = p.z;
var f = "12px ui-sans-serif, system-ui, sans-serif";
ctx.font = f;
ctx.lineWidth = 2;

// layout
var axY = H * 0.34;
var x0 = W * 0.12;              // ring centre on screen
var mPerPx = 0.45 / (W * 0.72); // metres per pixel along the axis
var ringPx = R / mPerPx * 0.55; // vertical half-height of the ring ellipse

// axis line
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0 - W * 0.06, axY); ctx.lineTo(W - 14, axY); ctx.stroke();

// the ring, seen edge-on-ish as an ellipse
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2.5;
ctx.beginPath();
ctx.ellipse(x0, axY, Math.max(4, ringPx * 0.34), Math.max(6, ringPx), 0, 0, Math.PI * 2);
ctx.stroke();

ctx.fillStyle = C.ink;
ctx.fillText("ring, charge Q, radius R", x0 - 10, axY - Math.max(6, ringPx) - 10);

// probe point P at distance z
var px = x0 + z / mPerPx;
if (px > W - 24) px = W - 24;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(px, axY, 4, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("P", px - 4, axY + 20);

// z measurement
ctx.strokeStyle = C.faint;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(x0, axY + 34); ctx.lineTo(px, axY + 34); ctx.stroke();
ctx.beginPath(); ctx.moveTo(x0, axY + 30); ctx.lineTo(x0, axY + 38); ctx.stroke();
ctx.beginPath(); ctx.moveTo(px, axY + 30); ctx.lineTo(px, axY + 38); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("z = " + z.toFixed(2) + " m", (x0 + px) / 2 - 24, axY + 52);

// two sample elements and their dE vectors, to show the cancelling
var top = axY - Math.max(6, ringPx), bot = axY + Math.max(6, ringPx);
var pairs = [top, bot];
for (var i = 0; i < 2; i++) {
  var ey = pairs[i];
  ctx.strokeStyle = C.faint;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(x0, ey); ctx.lineTo(px, axY); ctx.stroke();
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(x0, ey, 3, 0, Math.PI * 2); ctx.fill();
}
ctx.fillStyle = C.ink;
ctx.fillText("dq", x0 - 24, top + 4);
ctx.fillText("dq", x0 - 24, bot + 4);

// field value and arrow
function Efield(zz) { return k * Q * zz / Math.pow(zz * zz + R * R, 1.5); }
var E = Efield(z);
var zpk = R / Math.SQRT2;
var Emax = Efield(zpk);
var arrow = 18 + 46 * (Emax > 0 ? E / Emax : 0);
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2.5;
ctx.beginPath(); ctx.moveTo(px, axY); ctx.lineTo(px + arrow, axY); ctx.stroke();
ctx.beginPath();
ctx.moveTo(px + arrow, axY); ctx.lineTo(px + arrow - 8, axY - 5); ctx.lineTo(px + arrow - 8, axY + 5);
ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText("E on axis", px + 6, axY - 12);

// graph of E against z
var gy = H * 0.92, gx0 = 34, gx1 = W - 14, gtop = H * 0.58;
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx1, gy); ctx.stroke();
ctx.beginPath(); ctx.moveTo(gx0, gy); ctx.lineTo(gx0, gtop); ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText("E", gx0 - 16, gtop + 10);
ctx.fillText("z", gx1 - 10, gy + 16);

var zmax = 0.45;
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
for (var j = 0; j <= 160; j++) {
  var zz = zmax * j / 160;
  var gxp = gx0 + (gx1 - gx0) * zz / zmax;
  var gyp = gy - (gy - gtop) * (Emax > 0 ? Efield(zz) / Emax : 0) * 0.92;
  if (j === 0) ctx.moveTo(gxp, gyp); else ctx.lineTo(gxp, gyp);
}
ctx.stroke();

// peak marker
var pkx = gx0 + (gx1 - gx0) * Math.min(zpk, zmax) / zmax;
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(pkx, gy); ctx.lineTo(pkx, gtop + 4); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.ink;
ctx.fillText("z = R/sqrt(2)", Math.min(pkx + 4, gx1 - 78), gtop + 14);

// current z marker on the graph
var curx = gx0 + (gx1 - gx0) * Math.min(z, zmax) / zmax;
var cury = gy - (gy - gtop) * (Emax > 0 ? E / Emax : 0) * 0.92;
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.arc(curx, cury, 4, 0, Math.PI * 2); ctx.fill();

out.note = "E = " + E.toFixed(1) + " N/C   |   peak at z = " + zpk.toFixed(3) +
  " m, where E = " + Emax.toFixed(1) + " N/C";
